   if s:
    cnt=int((lab[s]==i).sum())
    if 3<=cnt<300:
     yy,xx=np.where(lab[s]==i);comps.append((cnt,round(xx.mean()+s[1].start,1),round(yy.mean()+s[0].start,1),a[yy+s[0].start,xx+s[1].start].mean(axis=0).round().tolist()))
  print(fn, sorted(comps,reverse=True)[:30])
