from PIL import Image
import numpy as np
from scipy.ndimage import label,find_objects
for fn in ['/app/runs/038_park_left_wait/last/ego.jpg','/app/runs/020_lift_handle_test_wait/last/ego.jpg','/app/runs/000_initial/last/ego.jpg']:
 try:a=np.array(Image.open(fn))
 except: continue
 r,g,b=a[:,:,0].astype(int),a[:,:,1].astype(int),a[:,:,2].astype(int)
 # bluish brighter than cup shadow
 for name,mask in [('a',(b>65)&(g>35)&(r<35)&(b-g>18)),('b',(b>65)&(g>40)&(r<50)&(b-r>35)&(g-r>20))]:
  lab,n=label(mask);out=[]
  for i,s in enumerate(find_objects(lab),1):
   if not s:continue
   cnt=int((lab[s]==i).sum())
   if cnt>=3:
    yy,xx=np.where(lab[s]==i); cx=xx.mean()+s[1].start;cy=yy.mean()+s[0].start
    if 200<cx<600 and 120<cy<400:out.append((cnt,round(cx,1),round(cy,1),a[int(cy),int(cx)].tolist()))
  print(fn,name,sorted(out,reverse=True)[:20])
